class _545_BoundaryBinaryTree:
    def boundaryOfBinaryTree(self, root: Optional['TreeNode']) -> List[int]:
        if not root:
            return []

        def is_leaf(n): return not n.left and not n.right

        def left_boundary(n):
            res = []
            while n and not is_leaf(n):
                res.append(n.val)
                n = n.left if n.left else n.right
            return res

        def leaves(n):
            if not n:   return []
            if is_leaf(n): return [n.val]
            return leaves(n.left) + leaves(n.right)

        def right_boundary(n):
            res = []
            while n and not is_leaf(n):
                res.append(n.val)
                n = n.right if n.right else n.left
            return res[::-1]

        if is_leaf(root):
            return [root.val]
        return [root.val] + left_boundary(root.left) + leaves(root) + right_boundary(root.right)

