class _301_RemoveInvalidParentheses_Brute:
    def removeInvalidParentheses(self, s):
        from collections import deque
        def is_valid(t):
            bal=0
            for c in t:
                if c=='(': bal+=1
                elif c==')': bal-=1; 
                if bal<0: return False
            return bal==0
        queue=deque([s]); visited={s}; found=False; result=[]
        while queue:
            curr=queue.popleft()
            if is_valid(curr): found=True; result.append(curr)
            if found: continue
            for i in range(len(curr)):
                if curr[i] not in '()': continue
                nxt=curr[:i]+curr[i+1:]
                if nxt not in visited: visited.add(nxt); queue.append(nxt)
        return result

