class _301_RemoveInvalidParentheses:
    def removeInvalidParentheses(self, s):
        min_open = min_close = 0
        for ch in s:
            if ch == '(':
                min_open += 1
            elif ch == ')':
                if min_open > 0: min_open -= 1
                else: min_close += 1
        result = set()
        def backtrack(idx, open_count, close_count, rem_open, rem_close, path):
            if idx == len(s):
                if rem_open == 0 and rem_close == 0 and open_count == close_count:
                    result.add(path)
                return
            ch = s[idx]
            if ch == '(' and rem_open > 0:
                backtrack(idx+1, open_count, close_count, rem_open-1, rem_close, path)
            if ch == ')' and rem_close > 0:
                backtrack(idx+1, open_count, close_count, rem_open, rem_close-1, path)
            if ch == '(':
                backtrack(idx+1, open_count+1, close_count, rem_open, rem_close, path+ch)
